import {QUESTS,REWARDS,CONTENT,ITEMS} from './data.mjs';
import {addCount,weight,addXP} from './rules.mjs';
export function currentStep(state,id){const a=state.quests.active[id];return a?QUESTS[id].steps[a.step]:null}
export function canAccept(state,id){const q=QUESTS[id];if(!q)return '找不到任務';if(state.quests.active[id])return '已接取任務';if(state.quests.completed.includes(id)&&q.repeatability==='once')return '任務已完成';if(state.player.level<q.prerequisites.minimum_level)return '等級不足';if(!q.prerequisites.completed_quest_ids.every(x=>state.quests.completed.includes(x)))return '前置任務未完成';if(!q.class_conditions.includes(CONTENT.classes[state.player.classId]))return '職業不符';return null}
export function availableQuests(state){return Object.values(QUESTS).filter(q=>!canAccept(state,q.id))}
export function acceptQuest(state,id,npcId){const q=QUESTS[id],error=canAccept(state,id);if(error)return{ok:false,error};if(q.start_npc_id!==npcId)return{ok:false,error:'請向任務委託人接取'};state.quests.active[id]={step:0,count:0,landmarks:[]};questEvent(state,{type:'talk',npcId,manual:true});return{ok:true}}
export function abandonQuest(state,id){if(!state.quests.active[id])return{ok:false,error:'尚未接取'};delete state.quests.active[id];return{ok:true}}
export function questEvent(state,event){for(const[id,a]of Object.entries(state.quests.active)){const step=currentStep(state,id);if(!step)continue;let complete=false;if(step.type==='talk'&&event.type==='talk'&&event.manual&&event.npcId===step.npc_id)complete=true;if(step.type==='travel'&&event.type==='travel'&&event.manual&&event.mapId===step.map_id&&(!step.mode||step.mode===event.mode))complete=true;if(step.type==='survey'&&event.type==='survey'&&event.manual&&event.mapId===step.map_id&&step.landmark_ids.includes(event.landmarkId)){if(!a.landmarks.includes(event.landmarkId))a.landmarks.push(event.landmarkId);complete=a.landmarks.length>=step.unique_landmarks}if(step.type==='kill'&&event.type==='kill'&&event.mapId===(step.map_id||step.population_ref)&&step.target_monster_ids.includes(event.monsterId)&&(!step.target_population_ids||step.target_population_ids.includes(event.populationId))){a.count++;complete=a.count>=step.quantity}if(complete){a.step++;a.count=0;a.landmarks=[]}}}
export function claimQuest(state,id,npcId){const q=QUESTS[id],a=state.quests.active[id],step=currentStep(state,id);if(!q||!a||step?.type!=='return_and_report'||q.end_npc_id!==npcId)return{ok:false,error:'目標尚未完成，或回報對象不符'};if(state.player.level<q.prerequisites.minimum_level||!q.prerequisites.completed_quest_ids.every(x=>state.quests.completed.includes(x))||!q.class_conditions.includes(CONTENT.classes[state.player.classId]))return{ok:false,error:'等級、職業或前置條件不符'};const reward=REWARDS[q.reward_ref],w=weight(state),added=reward.items.reduce((n,r)=>n+ITEMS[r.item_id].weight*r.quantity,0);if(w.total+added>w.capacity)return{ok:false,error:'行囊負重不足以領取報酬'};for(const r of reward.items)addCount(state.inventory,r.item_id,r.quantity);state.player.gold+=reward.currency;if(reward.xp)addXP(state,reward.xp);delete state.quests.active[id];if(!state.quests.completed.includes(id))state.quests.completed.push(id);return{ok:true,reward}}
